def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    threat_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    threat_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    cindy_bid = None
    cindy_budget = 0.0
    cindy_alive = False
    if 'Cindy' in opponents_status:
        c = opponents_status['Cindy']
        cindy_alive = bool(c.get('alive'))
        cindy_budget = float(c.get('budget', 0.0))
        prev = c.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            cindy_bid = float(prev.get('bid'))

    urgent = hp <= 4 or no_water >= 1
    critical = hp <= 2 or no_water >= 2

    if critical:
        target = max(92.0, (cindy_bid + 2.0) if cindy_bid is not None else 96.0)
        return float(min(budget, target))

    if slots >= 2:
        if urgent:
            if cindy_alive and cindy_bid is not None:
                target = max(58.0, min(88.0, cindy_bid * 0.72))
            else:
                target = max(52.0, avg_prev + 4.0)
        else:
            if max_prev >= 100:
                target = 31.0
            elif max_prev >= 70:
                target = 38.0
            else:
                target = 44.0
    else:
        if cindy_alive and cindy_budget > 0:
            if urgent:
                target = max(98.0, (cindy_bid + 3.0) if cindy_bid is not None else 102.0)
            else:
                target = max(72.0, min(96.0, (cindy_bid - 6.0) if cindy_bid is not None else 78.0))
        else:
            target = max(55.0, avg_prev + 6.0)

    if budget < DAILY_SALARY * 1.2 and not urgent:
        target = min(target, 42.0)

    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    base_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.8
    else:
        current_supply = day_context['supply']
        potential_water_takers = int(current_supply // WATER_REQ)

        if potential_water_takers <= 1: 
            if highest_prev_bid > DAILY_SALARY * 0.7:
                base_bid = highest_prev_bid + 5
            else:
                base_bid = DAILY_SALARY * 0.75
        elif potential_water_takers > 1:
            if highest_prev_bid > DAILY_SALARY * 0.6:
                base_bid = highest_prev_bid + 2
            else:
                base_bid = DAILY_SALARY * 0.6

    final_bid = min(my_status['budget'], base_bid)

    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 30.0

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], DAILY_SALARY * 0.9))

    if day_context['supply'] < WATER_REQ * 2:
        return float(min(my_status['budget'], avg_prev * 1.1))

    return float(min(my_status['budget'], max(25.0, avg_prev * 0.8)))
